/// <summary>
/// MPJ_28153 Interbranch Transfers	DCP 01/08/2022
/// </summary>
[ExtensionOf(tableStr(WMSPickingRoute))]
final class METWMSPickingRouteTable_Extension
{
}

Method.Source:
    /// <summary>
    /// Finishes multiple WMSPicking routes.
    /// </summary>
    /// <param name = "_packedList">A packed list of picking route ids, for routes that should be finished.</param>
    public static void finishMulti(container _packedList)
    {
        next finishMulti(_packedList); 

        WMSPickingRoute::METAdjustShipRemainMulti(_packedList);
        WMSPickingRoute::METUpdateInterncompanyPO(_packedList);
        WMSPickingRoute::setOrdersForRepricing(_packedList);
        using (METCustomerMDFPricingContext context = new METCustomerMDFPricingContext())
        {
            WMSPickingRoute::METCustomerMDFCalculation(_packedList);
        }
    }

    /// <summary>
    /// set eligible orders for repricing after picking
    /// </summary>
    /// <param name = "_metPackedList">packedList</param>
    public static void setOrdersForRepricing(container   _metPackedList)
    {
        List                metPickingRouteIdList;
        ListEnumerator      metListEnumerator;
        WMSPickingRouteId   metPickingRouteId;
        SalesTable          salesTable;
        CustTable           custTable;
        METCustTable        metCustTable;
        SalesLine           salesLine;
        METIndustryKeyTable metIndustryKeyTable;
        METSalesInvoiceIndicatorView    metSalesInvoiceIndicatorView;

        if (!_metPackedList)
        {
            return;
        }

        metPickingRouteIdList = List::create(_metPackedList);

        if (!metPickingRouteIdList)
        {
            return;
        }
        
        metListEnumerator = metPickingRouteIdList.getEnumerator();

        while (metListEnumerator.moveNext())
        {
            WMSOrderTrans   wmsOrderTrans;
            WMSPickingRoute pickingRouteTable;
            
            metPickingRouteId   = metListEnumerator.current();
            pickingRouteTable   = WMSPickingRoute::find(metPickingRouteId);

            select firstonly salesTable
                where salesTable.SalesId == pickingRouteTable.transRefId
                join metCustTable
                    where metCustTable.AccountNum == salesTable.CustAccount
                join metIndustryKeyTable
                    where metIndustryKeyTable.IndustryKey == metCustTable.IndustryKey;

            if (metIndustryKeyTable.RepriceAfterPicking)
            {   
                ttsbegin;

                while select forupdate salesLine
                    order by salesLine.LineNum asc
                    where salesLine.SalesId     == salesTable.SalesId
                {
                    select firstonly CimponentInvoiceIndicator from metSalesInvoiceIndicatorView
                        where metSalesInvoiceIndicatorView.InventTransId  == salesLine.InventTransId;

                    if (metSalesInvoiceIndicatorView.CimponentInvoiceIndicator == METInvoiceIndicator::B)
                    {
                        SalesUpdateRemain::updateDeliveryRemainder(salesLine, 0, 0);
                    }
                   
                    salesLine.metDeletePriceComponents();
                    salesLine.SalesPrice = 0;
                    salesLine.LineAmount = 0;
                    salesLine.update();
                }  

                METSalesTable metSalesTable = METSalesTable::findByRefRecId(salesTable.RecId, true);
                if (metSalesTable)
                {
                    metSalesTable.OrderProcessingStatus = METSalesOrderProcessingStatus::RepriceRequired;
                    metSalesTable.update();
                }
                ttscommit;
            }
        }
    }

    /// <summary>
    /// Added for the FSD-CB274 intercompany transfer.
    /// Fetch the Replenishment purchase order reference and update the quantity on it's lines.
    /// </summary>
    public static void METUpdateInterncompanyPO(container _metPackedList)
    {
        List                metPickingRouteIdList;
        boolean             updateDone = false;
        PurchLine           purchLine;
        SalesLine           salesLine;
        PurchTable          purchTable;
        ListEnumerator      metListEnumerator;
        WMSPickingRouteId   metPickingRouteId;

        if (!_metPackedList)
        {
            return;
        }

        metPickingRouteIdList = List::create(_metPackedList);

        if (!metPickingRouteIdList)
        {
            return;
        }
        
        metListEnumerator = metPickingRouteIdList.getEnumerator();

        while (metListEnumerator.moveNext())
        {
            WMSOrderTrans   wmsOrderTrans;
            WMSPickingRoute pickingRouteTable;
            
            metPickingRouteId   = metListEnumerator.current();
            pickingRouteTable   = WMSPickingRoute::find(metPickingRouteId);

            while select salesLine
                where salesLine.SalesId == pickingRouteTable.transRefId
                && salesLine.METReplenishmentPOReference != ''
            {
                select firstonly wmsOrderTrans
                    where wmsOrderTrans.inventTransRefId == salesLine.SalesId
                    && wmsOrderTrans.inventTransType == InventTransType::Sales;

                //Call the helper class to update the PO line and confirm the PO.
                METSalesOrderProcessHelper salesProcessHelper = new METSalesOrderProcessHelper();
                salesProcessHelper.updateIntercompanyPOAndConfirm(salesLine, wmsOrderTrans.qty);
            } 
        }
        
    }

    /// <summary>
    /// Reduce the Ship Remain qty to match what was pickied
    /// </summary>
    /// <param name = "_metPackedList">A packed list of picking route ids</param>
    public static void METAdjustShipRemainMulti(container _metPackedList)
    {
        List                metPickingRouteIdList;
        ListEnumerator      metListEnumerator;
        WMSPickingRouteId   metPickingRouteId;

        if (!_metPackedList)
        {
            return;
        }

        metPickingRouteIdList = List::create(_metPackedList);

        if (!metPickingRouteIdList)
        {
            return;
        }
        
        metListEnumerator = metPickingRouteIdList.getEnumerator();

        while (metListEnumerator.moveNext())
        {
            metPickingRouteId = metListEnumerator.current();

            InventTransferLine::METAdjustShipRemain(metPickingRouteId);
        }
    }

    /// <summary>
    /// Calculate Customer MDF for all WMSPickingRouteId in the packed list
    /// </summary>
    /// <param name = "_metPackedList">container</param>
    public static void METCustomerMDFCalculation(container _metPackedList)
    {
        List                metPickingRouteIdList;
        ListEnumerator      metListEnumerator;
        WMSPickingRouteId   metPickingRouteId;

        if (!_metPackedList)
        {
            return;
        }

        metPickingRouteIdList = List::create(_metPackedList);

        if (!metPickingRouteIdList)
        {
            return;
        }
        
        metListEnumerator = metPickingRouteIdList.getEnumerator();

        while (metListEnumerator.moveNext())
        {
            metPickingRouteId = metListEnumerator.current();

            METCustomerMDFCalculation_PickingRoute custMDFCalculation = new METCustomerMDFCalculation_PickingRoute();
            custMDFCalculation.parmWMSPickingRouteID(metPickingRouteId);
            custMDFCalculation.process();
        }
    }

    /// <summary>
    /// CB626_TMSEngineSOPackingSlip
    /// Retrieve the WMS picking list number from the FO picking list number
    /// </summary>
    /// <param name = "_pickingRouteId">FO picking list number</param>
    /// <param name = "_isCSDWarehouse">Is CSD warehouse</param>
    /// <param name = "_internalCrossDock">Internal cross dock order</param>
    /// <returns>WMS picking list number</returns>
    public static METWMSPicklistNumber METGetWMSPicklistNumber(WMSPickingRouteID _pickingRouteId, METCSDWarehouse _isCSDWarehouse, METInternalCrossDockOrder _internalCrossDock)
    {
        METWMSPicklistNumber ret;

        // search for the SO Pick List with “Picking route” = PickListID, set:
        WMSPickingRoute wmsPickingRouteSO = WMSPickingRoute::find(_pickingRouteId);

        // If the SO is for a warehouse that is marked as “Is CSD warehouse” = Yes or the SO has “Internal Cross Dock” = Yes
        if (_isCSDWarehouse || _internalCrossDock)
        {
            // RelatedTOPickListID = the SO Pick list’s “Source TO Picking Route”
            WMSPickingRoute wmsPickingRouteTO = WMSPickingRoute::find(wmsPickingRouteSO.METTransferOrderPickingRouteId);

            // METPicklistReference as the link between FO picklist number and CCR/WMS pickList number
            ret = METPicklistReference::find(wmsPickingRouteTO.pickingRouteID).WMSPicklistNumber;
        }

        if (!ret)
        {
            ret = METPicklistReference::find(wmsPickingRouteSO.pickingRouteID).WMSPicklistNumber;
        }

        return ret;
    }

    /// <summary>
    /// Update method overridden to call the wave status update method when a sales order picking route is completed.
    /// </summary>
    public void update()
    {
        WMSPickingRoute wmsPickingRouteOrig = this.orig();
        next update();

        if (this.transType == InventTransType::Sales    &&
            wmsPickingRouteOrig.expeditionStatus != WMSExpeditionStatus::Complete &&
            this.expeditionStatus == WMSExpeditionStatus::Complete)
        {
            this.metUpdateWaveStatus();
        }

        //CBNF019_Observability_TransferOrder
        if (this.transType == InventTransType::TransferOrderShip  &&
            wmsPickingRouteOrig.expeditionStatus != WMSExpeditionStatus::Complete &&
            this.expeditionStatus == WMSExpeditionStatus::Complete)
        {         
            METTelemetryTransferOrderPickedInfoEvent::runTelemetryEvent(this.transRefId);
        }
        //CBNF019_Observability_TransferOrder
    }

    /// <summary>
    /// Update the wave status to closed if all sales orders in the wave are completed.
    /// </summary>
    public void metUpdateWaveStatus()
    {
        WMSPickingRoute wmsPickingRoute = this;
        WMSPickingRoute wmsPickingRouteLoc;
        SalesId          salesId = wmsPickingRoute.transRefId;
        METWaveTable    metWaveTable;
        METWaveLine     metWaveLine;
        METWaveId       metWaveId;

        select firstonly1 WaveId from metWaveLine
            where metWaveLine.DocumentNumber == salesId &&
                metWaveLine.Type == METType::SalesOrder;

        metWaveId = metWaveLine.WaveId;

        if (metWaveId == '')
        {
            return;
        }

        METWaveLine metWaveLineOther;

        SalesTable salesTable;

        select firstonly RecId, DocumentNumber from metWaveLineOther
            where metWaveLineOther.WaveId == metWaveId
            && metWaveLineOther.Type == METType::SalesOrder
         notexists join wmsPickingRouteLoc
            where wmsPickingRouteLoc.transRefId == metWaveLineOther.DocumentNumber
            && wmsPickingRouteLoc.transType == InventTransType::Sales;

        if (metWaveLineOther.RecId)
        {
            // At least one other wave line exists without picklist records

            // Check if the sales order is NOT cancelled
            select firstonly RecId from salesTable
                where salesTable.SalesId == metWaveLineOther.DocumentNumber
                && salesTable.SalesStatus != SalesStatus::Canceled;

            if (salesTable.RecId)
            {
                // At least one NON-CANCELLED wave line exists without picklist records
                return;
            }
        }

        
        select firstonly1 RecId from metWaveLine
                where metWaveLine.WaveId == metWaveId
            exists join wmsPickingRouteLoc
                where wmsPickingRouteLoc.transRefId == metWaveLine.DocumentNumber   &&
                    wmsPickingRouteLoc.transType == InventTransType::Sales &&
                    wmsPickingRouteLoc.expeditionStatus != WMSExpeditionStatus::Complete
            notexists join salesTable
                where salesTable.SalesId == metWaveLine.DocumentNumber &&
            salesTable.SalesStatus == SalesStatus::Canceled;

        if (metWaveLine.RecId == 0)
        {
            ttsbegin;
            metWaveTable = METWaveTable::find(metWaveId, true);

            if (metWavetable.RecId)
            {
                metWaveTable.WaveStatus = METCSDWaveStatus::Closed;
                metWaveTable.update();

                Info(strFmt("@MET:WaveStatusUpdate", metWaveId));
            }
            ttscommit;
        }
    }

    public boolean checkIfAllLinesArePicked()
    {
        WMSOrderTrans       wmsOrderTransLocal;
        boolean             allLinesPicked;

        if (!this.PickingRouteID)
        {
            return allLinesPicked;
        }

        select firstonly RecId from wmsOrderTransLocal
            where wmsOrderTransLocal.RouteId          == this.PickingRouteID  &&
                 (wmsOrderTransLocal.ExpeditionStatus == WMSExpeditionStatus::None       ||
                  wmsOrderTransLocal.ExpeditionStatus == WMSExpeditionStatus::Registered ||
                  wmsOrderTransLocal.ExpeditionStatus == WMSExpeditionStatus::Activated  ||
                  wmsOrderTransLocal.ExpeditionStatus == WMSExpeditionStatus::Started);

        if (!wmsOrderTransLocal.RecId)
        {
            allLinesPicked = true;
        }

        return allLinesPicked;
    }
